<script setup lang="ts">
import { notify } from '../../lib/notifications';
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { Plus, Trash2, Save, Pencil, History, Check, LoaderCircle } from '@lucide/vue';
import BaseSelect from '../../components/BaseSelect.vue';
import { api, message, formatDate } from '../../api';
import { scenarios, type AutomationRule } from '../../../../shared/automation';
const rules=ref<AutomationRule[]>([]),selected=ref(''),error=ref(''),busy=ref(false),tab=ref('criteria');
const editing=ref(false);const form=ref<Pick<AutomationRule,'name'|'kind'|'sop'|'references'|'criteria'|'scenarios'>>({name:'',kind:'site',sop:'',references:'',criteria:[],scenarios:Object.keys(scenarios) as (keyof typeof scenarios)[]});
const saved=ref('');const dirty=computed(()=>editing.value&&JSON.stringify(form.value)!==saved.value);defineExpose({dirty});
const total=computed(()=>Math.round(form.value.criteria.reduce((sum,c)=>sum+(Number(c.weight)||0),0)*100)/100);
const selectedRule=computed(()=>rules.value.find(r=>r.id===selected.value)||rules.value.at(-1));
function from(rule:AutomationRule){return {name:rule.name,kind:rule.kind,scenarios:rule.scenarios?[...rule.scenarios]:Object.keys(scenarios).filter(s=>rule.kind==='app'?s==='app-template':s!=='app-template') as (keyof typeof scenarios)[],sop:rule.sop,references:rule.references,criteria:rule.criteria.map(c=>({...c,viewports:[...c.viewports],scopes:[...c.scopes]}))};}
function edit(){if(!selectedRule.value)return;form.value=from(selectedRule.value);form.value.name+=' · 新版本';saved.value=JSON.stringify(form.value);editing.value=true;error.value='';}
function add(){let n=form.value.criteria.length+1;while(form.value.criteria.some(c=>c.id===`criterion-${n}`))n++;form.value.criteria.push({id:`criterion-${n}`,label:'',weight:0,instruction:'',required:false,viewports:['desktop','mobile'],scopes:['homepage','site']});}
async function load(){try{rules.value=(await api<{items:AutomationRule[]}>('/automation/rules')).items;selected.value=rules.value.at(-1)?.id||'';}catch(e){error.value=message(e);}}
async function publish(){busy.value=true;error.value='';try{const rule=await api<AutomationRule>('/automation/rules',{method:'POST',body:JSON.stringify(form.value)});rules.value.push(rule);selected.value=rule.id;editing.value=false;notify.success('新版本已保存并启用，已有任务与报告保留原规则。');localStorage.removeItem('automation-rule-draft');}catch(e){error.value=message(e);}finally{busy.value=false;}}
function saveDraft(){localStorage.setItem('automation-rule-draft',JSON.stringify(form.value));saved.value=JSON.stringify(form.value);notify.success('草稿已保存在此浏览器，尚未启用。');}
function restore(){try{const draft=localStorage.getItem('automation-rule-draft');if(draft){form.value=JSON.parse(draft);saved.value=JSON.stringify(form.value);editing.value=true;notify.success('已恢复本地草稿。');}}catch{error.value='草稿无法读取';}}
const hasDraft=ref(false);
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>{void load();hasDraft.value=!!localStorage.getItem('automation-rule-draft');window.addEventListener('beforeunload',beforeUnload);});onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload));
</script>
<template><header class="page-header"><div><h1>评测规则</h1></div><div class="toolbar-actions"><button v-if="!editing&&hasDraft" class="button secondary" @click="restore"><History :size="16" />恢复草稿</button><button v-if="!editing" class="button primary" :disabled="!selectedRule" @click="edit"><Pencil :size="16" />编辑为新版本</button><template v-else><button class="button secondary" @click="saveDraft"><Save :size="16" />保存草稿</button><button class="button primary" :disabled="busy||total!==100||!form.criteria.length" form="automation-rule-form"><LoaderCircle v-if="busy" class="spin" :size="16" /><Check v-else :size="16" />保存并启用</button></template></div></header>
<p v-if="error" class="alert error" role="alert">{{error}}</p>
<template v-if="!editing"><section class="panel settings-panel"><label class="field"><span>已发布版本</span><BaseSelect v-model="selected" :options="rules.slice().reverse().map((rule) => ({ value: rule.id, label: (rule.name) + ' · ' + (rule.kind==='site'?'Site':'App') + ' · ' + (formatDate(rule.createdAt)) }))" /></label><template v-if="selectedRule"><div class="rule-version-meta"><span>{{selectedRule.kind==='site'?'Site':'App'}} 规则</span><code>{{selectedRule.hash.slice(0,16)}}</code><span>{{rules.filter(r=>r.kind===selectedRule?.kind).at(-1)?.id===selectedRule.id?'当前启用版本':'历史版本'}}</span></div><div class="table-scroll"><table class="task-table"><thead><tr><th>指标</th><th>权重</th><th>适用范围</th><th>审核标准</th></tr></thead><tbody><tr v-for="c in selectedRule.criteria" :key="c.id"><td>{{c.label}}<span v-if="c.required" class="table-subtitle warning-text">必过项</span></td><td>{{c.weight}}%</td><td>{{c.scopes.map(s=>s==='homepage'?'首页':'全站').join(' / ')}}<span class="table-subtitle">{{c.viewports.map(v=>v==='desktop'?'PC':v==='mobile'?'移动端':'业务').join(' / ')}}</span></td><td class="wrapping-cell">{{c.instruction}}</td></tr></tbody></table></div><details class="version-entry"><summary>评测 SOP</summary><pre class="resource-description">{{selectedRule.sop}}</pre></details><details v-if="selectedRule.references" class="version-entry"><summary>参考资料与案例</summary><pre class="resource-description">{{selectedRule.references}}</pre></details></template></section></template>
<form v-else id="automation-rule-form" @submit.prevent="publish"><section class="panel settings-panel"><div class="criterion-options"><span>适用场景</span><label v-for="(label,key) in scenarios" :key="key" class="check-label"><input v-model="form.scenarios" type="checkbox" :value="key" />{{label}}</label></div><div class="form-grid"><label class="field"><span>版本名称</span><input v-model="form.name" class="input" required maxlength="200" /></label><label class="field"><span>适用类型</span><BaseSelect v-model="form.kind" :options="[{ value: 'site', label: 'Site' }, { value: 'app', label: 'AI App' }]" /></label></div></section><div class="segmented view-tabs"><button v-for="item in [{id:'criteria',label:'评分指标'},{id:'sop',label:'评测 SOP'},{id:'references',label:'资料与案例'}]" :key="item.id" type="button" :class="{selected:tab===item.id}" @click="tab=item.id">{{item.label}}</button></div>
<section v-show="tab==='criteria'" class="panel settings-panel"><div class="section-heading"><h2>评分指标</h2><strong :class="total===100?'success-text':'warning-text'">权重合计 {{total}}%</strong></div><article v-for="(c,index) in form.criteria" :key="index" class="criterion-editor"><div class="criterion-heading"><strong>{{index+1}}</strong><button type="button" class="icon-button danger-icon" aria-label="删除指标" @click="form.criteria.splice(index,1)"><Trash2 :size="17" /></button></div><div class="form-grid three-columns"><label class="field"><span>指标名称</span><input v-model="c.label" class="input" required maxlength="100" /></label><label class="field"><span>指标 ID</span><input v-model="c.id" class="input" pattern="[a-z][a-z0-9-]{0,60}" required /></label><label class="field"><span>权重 %</span><input v-model.number="c.weight" class="input" type="number" min="0" max="100" step="0.1" required /></label></div><label class="field"><span>审核标准</span><textarea v-model="c.instruction" class="input" rows="3" required /></label><div class="criterion-options"><label class="check-label"><input v-model="c.required" type="checkbox" />必过项</label><span>适用范围</span><label class="check-label"><input v-model="c.scopes" type="checkbox" value="homepage" />首页</label><label class="check-label"><input v-model="c.scopes" type="checkbox" value="site" />全站</label><span>视口 / 业务</span><label v-for="v in [{id:'desktop',label:'PC'},{id:'mobile',label:'移动端'},{id:'business',label:'业务'}]" :key="v.id" class="check-label"><input v-model="c.viewports" type="checkbox" :value="v.id" />{{v.label}}</label></div></article><button type="button" class="button secondary" :disabled="form.criteria.length>=30" @click="add"><Plus :size="16" />添加指标</button></section>
<section v-show="tab==='sop'" class="panel settings-panel"><label class="field"><span>评测 SOP（Markdown）</span><textarea v-model="form.sop" class="input code-editor" rows="22" required /></label></section><section v-show="tab==='references'" class="panel settings-panel"><label class="field"><span>参考资料与案例（Markdown）</span><textarea v-model="form.references" class="input code-editor" rows="22" placeholder="评测示例、对照标准、URL 和工具使用说明" /></label></section></form>
</template>
